  ('ql_00001', 'pc_00001', 0, NULL, 4, 4, 4, 'Effektiv lossing. Kranen litt treg i starten.', 'u_per', '2026-10-15T05:04:00.000Z'),
  ('ql_00002', 'pc_00002', 0, NULL, 5, 5, 5, 'Presis og ryddig. Mannskapet hjalp med surring.', 'u_ola', '2026-10-03T10:40:00.000Z'),
  ('ql_00003', 'pc_00003', 1, 'Ankom 07:30, 1,5 t etter ETA. Fire mann ventet uten oppgaver.', 2, 4, 4, 'Ring skipper kvelden før for oppdatert ETA.', 'u_jonas', '2026-09-28T09:15:00.000Z'),
  ('ql_00004', 'pc_00004', 0, NULL, 5, 5, 5, 'Kom før tiden, alt klart til lossing.', 'u_per', '2026-09-24T08:52:00.000Z'),
  ('ql_00005', 'pc_00005', 0, NULL, 4, 4, 4, 'Litt venting på papirer, ellers greit.', 'u_jonas', '2026-09-19T13:20:00.000Z'),
  ('ql_00006', 'pc_00006', 0, NULL, 4, 4, 4, 'Godt samarbeid. Egen kran i god stand.', 'u_ola', '2026-09-12T16:30:00.000Z'),
  ('ql_00007', 'pc_00007', 1, 'Båtkrana stoppet to ganger under lossing. Ca. 2 t forsinkelse. Brukte egne stropper.', 2, 3, 1, 'Ha egne stropper klare neste gang.', 'u_ola', '2026-09-04T12:45:00.000Z'),
