  ('ql_00009', 'pc_00009', 1, 'Mannskap uten hjelm på kaia. 3 paller skadet ved lasting fra båtkran.', 2, 1, 2, 'Krev verneutstyr før lasting starter.', 'u_jonas', '2026-08-22T14:10:00.000Z'),
